insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('4441226','utility','4441226','US','4/10/1984','Apparatus for detecting the position of an object, for example, a licence plate, on the exterior of a car during the washing thereof includes a rotary brush which is driven by a hydraulic motor and is mounted on a pivotable structure adapted to move relative to and scrub the surface of the car as it advances therepast along a conveyor. A detection mechanism is positioned on an overhead structure to detect the position of the brush support structure corresponding to a position of the brush near the location of the license plate. A control mechanism responds to detection of the license plate and opens a fluid control valve, thereby reducing the rate of fluid flow to the hydraulic motor to slow the speed of brush rotation until the brush travels beyond the license plate.','Car washing apparatus','A',14,'pftaps19840410_wk15.zip',0,'[0.014280934,0.023482148,0.008484354,-0.015488192,0.044585317,0.026557289,0.038577445,-0.007636017,0.035658758,-0.034428738,-0.07292352,0.0053345026,0.08951486,-0.044791885,0.010174693,0.021536399,0.06951713,-0.016024942,0.015093771,-0.058019895,0.015887229,-0.041332606,-0.025796605,0.05191088,0.025150843,-0.030242011,-0.009004425,-0.04002562,-0.08380031,0.019047009,0.017003177,-0.044484187,0.03404423,0.008946477,0.015828943,-0.06716573,-0.0028505945,0.0131566515,0.004981669,0.043681003,0.050801944,-0.064930834,0.018871691,-0.036353737,-0.029876383,0.0025986584,-0.015296185,-0.040111057,0.039048467,-0.08107222,0.0059885434,0.0707537,0.06729502,-0.046045948,0.028744252,0.06848571,0.024215795,0.020303385,-0.012083664,-0.010197454,0.011955865,-0.03559972,-0.0010568167,0.045625817,-0.013818635,0.068710335,-0.025023198,0.018586215,0.019868493,-0.037811197,-0.0032516979,-0.032797556,0.03175221,-0.046393823,-0.047285818,-0.084217474,0.018690035,0.012586244,-0.0821