insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5964058','utility','5964058','US','10/12/1999','An electrosensing edge which automatically reverses the downward closing movement of a door such as a garage door when a sealing member and the electrosensing edge encounter an obstruction. The electrosensing edge is characterized by an elecricial cable which extends between two insulators located at each end of a metal bracket mounted on the leading edge of the door, inside the sealing member suspended from the bracket. The cable acts as a witch which is normally open, but is closed if the cable is forced against the bracket to ground the electrical circuit as the sealing member and cable strike the obstruction. Grounding of the cable trips a relay and causes the door actuator to immediately reverse downward movement of the door without injury or damage to the obstruction.','Electrosensing edge for door','A',13,'pftaps19991012_wk41.zip',0,'[0.0054375245,-0.022736728,-0.0051963483,-0.0013393126,0.05414068,0.0019756935,0.014557026,0.03620838,0.030801652,-0.028286388,-0.0022844689,0.021666987,0.06968876,-0.052362304,0.018803699,0.024407351,0.03535084,-0.034907036,-0.007297572,-0.045381416,-0.019770294,-0.04520917,-0.0298091,-0.013760078,0.01946741,-0.07828916,0.027078528,-0.029498199,-0.052389372,0.037930872,-0.03092596,-0.06087388,0.016136415,-0.010506012,0.026648792,-0.04453763,0.024469763,0.005777691,-0.023187114,0.023692328,0.061019894,0.006250223,0.017060226,-0.0129061015,-0.008264236,-0.018827211,-0.041955177,0.01726988,0.0302771,-0.062578864,-0.03311441,0.092846885,0.05724776,-0.027856374,0.00074107037,0.053373635,0.0372012,0.052873142,0.023874823,-0.015844313,-0.0337603,0.030787408,-0.070272386,0.01834473,-0.05651647,0.048618868,0.01930402,0.058171567,0.035168763,-0.02583108,-0.042149715,-0.088818125,0.016743895,-0.02674511,-0.04799636,0.019222638,-0.03522383,-0.03781678,-0