insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('5965848','utility','5965848','US','10/12/1999','A disposable portable electronic device has a body of prescribed length and thickness and constructed of an elongate, ribbon-like substrate of dielectric material, the substrate having a continuous length much greater than the length of the body, and a thickness much less than the thickness of the body, with conductors and components formed on the substrate, the dielectric material of the substrate having a high degree of flexibility such that the substrate is folded upon itself into at least shorter lengths juxtaposed with one another within the thickness of the body, and the juxtaposed lengths of the substrate are secured together to establish a self-sustaining structure which forms the body of the device.','Disposable portable electronic devices and method of making','A',15,'pftaps19991012_wk41.zip',0,'[-0.042268705,-0.054100495,0.02034795,-0.05371503,-0.012734094,0.014520397,-0.022501053,0.031371914,0.03220285,-0.046791725,-0.012162227,-0.007746974,0.02991818,-0.0747107,0.040780492,-0.00928548,0.05284806,-0.01783692,0.018540157,-0.0137697905,-0.0039816233,-0.089258716,-0.06143244,0.041759342,0.0457135,-0.09705237,-0.00032705374,-0.012561743,-0.08272713,0.08104403,0.009551233,-0.03740844,0.027955081,0.00018757995,0.029632756,-0.020939648,0.033679567,0.02071758,0.029491546,-0.027099654,0.052768577,-0.022089496,-0.013550951,-0.07863189,-0.008626051,-0.024381805,-0.0181363,0.03616495,0.02785612,-0.07253716,0.022574749,0.05244534,-0.06531424,-0.060502313,0.06601678,0.017444888,0.008700455,0.08799179,-0.004337357,0.05372915,-0.035901833,0.026055958,-0.04788474,0.05972665,-0.035761457,0.096280135,0.019640062,-0.008819444,0.013661131,-0.03757173,0.00888611,-0.018151766,-0.0038277267,-0.0495933,0.029485848,-0.0015491472,0.033703454,0.0011664587,-0.017005503,0.11195621,-0.008489936,-0.