insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8794319','utility','8794319','US','8/5/2014','A method of recovering liquid petroleum gases (LPGs) from a wellbore includes: performing a well treatment operation by injecting the LPGs into the wellbore to increase the wellbore pressure; flowing a fluid stream from the wellhead into a separation vessel, the fluid stream comprising the LPGs; reducing the pressure of the fluid stream from the wellbore pressure to a separation vessel pressure, the fluid stream in the separation vessel comprising the LPGs in liquid form and in vapour form; separating the vapour form from the liquid form; transferring the liquid form of the LPGs to a pressure vessel; and passing the vapour form through a condenser to condense the vapour form, and depositing the condensed vapour form into the pressure vessel.','Multistage separator vessel for capturing LPGs','B2',20,'ipg140805.xml',0,'[-0.040053517,0.012243819,0.021309083,-0.052484624,0.017819513,0.03261077,0.052563913,0.0352666,-0.01825345,-0.014856626,-0.046993777,-0.031514943,0.021195354,-0.035303324,0.0126024615,-0.0007529591,0.016785048,-0.056360886,0.0070663765,0.01163286,0.005851779,-0.038057745,-0.013002169,0.017963512,-0.024592038,-0.052992612,-0.021279875,0.004369609,-0.044169586,0.014894839,0.001179957,-0.058065653,0.101934284,-0.03285593,0.046025716,0.021986771,0.08312737,-0.02578568,-0.020414744,0.0052412585,0.018327154,-0.012436685,0.050808646,-0.0077251825,-0.013540037,0.05851219,-0.025150442,-0.022611704,0.03381122,-0.05970838,0.012760486,0.04854798,0.028419124,-0.035580073,0.007936674,0.013141408,0.028177865,0.039637446,-0.005067284,0.030836591,-0.0011049623,-0.041145016,0.008606053,-0.0405949,-0.095017545,0.087145165,0.030056005,0.051254734,0.017014833,-0.03770718,-0.04450997,-0.01794886,0.088332,-0.06191313,-0.007914146,-0.030663243,-0.0042936835,0.03347054,-0.006019736,0.01322455