insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8795515','utility','8795515','US','8/5/2014','Processes for the catalytic dechlorination of one or more hydrocarbon products involve contacting a mixture comprising the hydrocarbon product(s) and a carrier gas with a dechlorination catalyst under catalytic dechlorination conditions to provide a dechlorinated hydrocarbon product, HCl, and the carrier gas. The dechlorinated hydrocarbon product may be separated from the HCl and the carrier gas to provide liquid fuel or lubricating base oil.','Catalytic dechlorination processes to upgrade feedstock containing chloride as fuels','B2',18,'ipg140805.xml',0,'[-0.05722525,0.0078950925,-0.0002268455,-0.04497432,0.015103175,0.028682968,0.019433703,0.0050552073,0.024024423,-0.0058411807,0.002488723,-0.0039356174,0.06905385,-0.03999233,0.0010165687,0.004314651,0.02716281,-0.04440448,0.057208832,0.028408669,0.03475544,-0.050830457,-0.0141676,0.011107591,-0.019152038,-0.048892006,-0.025451383,-0.0074780933,-0.014530125,0.048127897,0.03990134,-0.06996855,0.10419454,0.016828991,0.035469312,0.023498045,0.08572322,-0.013378033,-0.046406213,-0.024021538,0.06942639,-0.021641828,0.023568148,-0.04608744,-0.010002293,0.022137297,-0.04221508,0.008576756,0.0988492,-0.021615554,0.01581458,0.037819978,-0.015232494,-0.11289547,0.00367158,-0.0033328196,-0.005690153,0.03654645,-0.06359055,0.0073907287,0.011656815,-0.0036555417,0.0053808154,-0.029210333,-0.041845623,0.04908665,0.064319655,-0.0063616745,-0.042678438,0.018729808,-0.032931212,-0.00019384096,0.045193654,-0.06128823,0.023214584,-0.04300076,0.02923543,0.032610282,-0.017602522,0.07080057,-0.07107377,-0.03158269,-0.07092813,0.030653685,0.0063295513,-0.022343323,-0.02570448,-0.050410718,-0.03985323,0.03690905,-0.006630802,-0.0068741404,0.031529903,0.01786302,-0.0012623733,0.011574449,0.01943911,0.09432125,0.061711982,-0.007456756,0.05897278,-0.008258