insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8801718','utility','8801718','US','8/12/2014','A method of using a tenolysis tool with a handle connected to at least two extension members which could be tines of a fork separated by a gap. Between the extension members and at least a portion of the handle may be a torque device selected from the group of a torque release and a torque indicator. By placing a tendon in the gap between the tines, the tool can be twisted so that the tendon is stretched under a torque.','Method of using a tendon tension device','B1',6,'ipg140812.xml',0,'[-0.017636802,-0.019581188,0.024256824,-0.048160102,0.030962665,0.07704247,-0.017539425,-0.07593893,0.0047601704,-0.044860948,-0.024695951,-0.012667519,0.07544012,-0.0915282,0.07798539,-0.010079762,0.053468242,-0.037089642,0.004429554,-0.019131368,0.0060694246,-0.020481886,-0.00026988497,0.020604221,0.004854036,-0.05617053,-0.0071086218,-0.02001125,-0.04500792,0.05333449,-0.07364085,-0.04927359,0.0028541128,0.016430356,0.033709787,-0.027145216,0.026904285,-0.014369514,-0.043628477,-0.004534812,0.06768631,-0.025740553,0.033589296,-0.06881473,0.028967561,-0.00016590554,-0.058306184,0.02675008,0.018641362,-0.0609712,0.018128583,0.04411304,0.012330658,-0.032772914,0.03434621,0.08698056,0.0104435915,0.021185573,-0.0067977766,0.0022656443,-0.0012960247,-0.02881049,0.020881841,-0.016230004,-0.07355067,0.041130386,0.0031799742,0.06743699,0.00015279563,-0.009277265,-0.0415569,-0.02679521,0.017086688,-0.037007127,-0.06548405,-0.06291696,-0.006178092,-0.023246057,-0.009392287,0.021453792,-0.07789313,-0.04490896,-0.06333385,-0.023169886,0.043295674,-0.043655533,0.00041706496,-0.010075695,0.020929381,-0.005745082,-0.01613562,-0.017348342,0.0128712375,0.010911664,0.03262017,-0.018925816,0.036062863,0.076892585,0.0313155,0.00850982,0.0075241243,0.02254574,-0.040592328,-0.032045234,-0.02972737,0.054357015,-0.0612