insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8814350','utility','8814350','US','8/26/2014','A contact lens incorporating one or more dynamic stabilization zones fabricated from a material that is readily deformable under eyelid pressure during blinking allows for the control over rotation of the contact lens on the eye. As the material deforms, the angle of contact between the eyelid and the one or more dynamic stabilization zones changes as does the rotational force acting on the contact lens.','Dynamic stabilization zones for contact lenses','B2',9,'ipg140826.xml',0,'[-0.029728714,-0.02134947,-0.021191653,-0.03742412,-0.017191855,0.05870591,0.027453162,-0.06980381,0.03806666,-0.033006582,-0.026542919,0.019756729,0.10335792,-0.07910043,0.034248564,-0.00706841,0.071690865,-0.06068978,0.015988184,-0.037810113,-0.0040146005,-0.050010018,-0.02219216,0.05048551,-0.010532591,-0.06853379,-0.018616375,-0.021867894,-0.057141844,0.03214031,-0.027485808,-0.021461003,0.03550356,0.02831645,0.0338508,-0.04740009,-0.0005877606,0.0102010295,0.029185398,0.0077361637,0.02934966,-0.056990523,-0.034054257,-0.021989396,-0.010712042,0.013334689,-0.010883605,0.006385994,0.023847122,-0.0646903,0.009036637,0.006564134,-0.010196475,-0.01889742,0.040178947,0.08564115,0.056009382,0.015276707,-0.020041335,0.0057115993,0.026845522,-0.0035522329,-0.026539369,0.02534341,-0.010758709,0.07741081,0.017420229,-0.006117481,0.05414433,-0.022100808,-0.0120326,-0.06330871,0.017244013,-0.07008718,-0.04268731,-0.039836045,0.019674491,-0.02335584,-0.056133013,0.06519183,-0.07391229,0.016016664,-0.017953198,-0.025179543,-0.037654605,-0.061782107,-0.048802737,0.0009541577,-0.014168228,0.00814175,-0.023790564,-0.086687796,0.028535618,0.0032433344,-0.02008808,0.059576318,0.051414676,0.09076013,0.04443815,0.014916013,-0.0028191162,0.051910922,0.022571752,-0.02107907,0.03335745,0.07756286,-0.034052428,-0.009605729,0.0