insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8816944','utility','8816944','US','8/26/2014','A display device, which includes a plurality of pixels; a data driver for outputting data signals to the pixels; a bias current outputting unit for outputting a bias current having a predetermined magnitude; a plurality of driving current outputting units for outputting driving currents to the pixels; and a first switch connected between the bias current outputting unit and the driving current outputting units for selecting one of the driving current outputting units to connect to the bias current outputting unit, wherein the magnitudes of the driving currents are substantially the same as a magnitude of the bias current.','Driving current output apparatus, method of manufacturing the same, display device and driving apparatus thereof','B2',15,'ipg140826.xml',0,'[-0.01852846,-0.017848885,0.029881364,-0.0017103724,-0.02262768,0.031167928,0.04021969,-0.003588896,0.05866809,0.016873065,-0.029219251,0.008856817,0.0135252355,-0.06888107,0.041011892,-0.019095736,0.03984936,-0.05771093,-0.001600051,-0.042647555,0.0027596208,-0.06441934,-0.0775223,-0.011276626,0.051333245,-0.10087356,0.024425441,-0.007923986,-0.057223126,0.10329771,0.05284583,-0.025899107,0.02010552,0.020612746,-0.0067159915,-0.010177354,0.010926978,0.018520392,-0.0059954426,-0.018396294,0.07897028,-0.02781709,-0.015518987,-0.039483413,-0.06312092,0.069101505,-0.07207654,0.06177984,0.04736851,-0.012857091,-0.0031030178,0.052027818,-0.011604375,-0.0153720975,0.024086878,-0.019197302,0.053875647,0.057104,0.008666913,0.018999418,0.010493741,-0.010564309,-0.01892397,0.04342095,-0.07672107,0.013098106,-0.0039360975,-0.0003123778,0.014850181,-0.01352638,-0.034701034,-0.038294118,0.060912523,-0.072691604,0.048671227,-0.042115863,0.052232098,-0.044974823,-0.052528024,0.070872724,-0.068040475,-0.071064055,-0.027372446,-0.005247370