insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8817831','utility','8817831','US','8/26/2014','A method and apparatus for spatially separating beams with different wavelengths is presented. The system includes: a light source (i.e. a laser with multiple harmonic output beams) with multiple wavelengths emitted along a single beam path or very nearly collinear beam paths, a path which connects the light source to a wavelength dependent beam separator, and a second path for blocking unwanted output wavelengths which connects the beam separation region to the laser output.','High power UV lasers','B1',25,'ipg140826.xml',0,'[-0.0012600354,-0.012645723,0.06190581,-0.04107552,0.003959211,0.07808549,-0.019774351,0.018495847,0.025282217,-0.038316835,-0.0036521854,-0.042340443,0.018167837,-0.014323573,0.027162774,0.018515138,0.022640988,-0.035358973,-0.0051622395,-0.028795263,-0.0100475075,-0.081531495,-0.060438458,0.042573817,0.025502278,-0.15176249,0.032194607,-0.04989988,-0.02340544,0.0766441,-0.03426961,-0.040114135,0.0059234956,-0.01180989,0.04117792,-0.017510807,0.024143362,0.027537245,-0.022601373,0.019071171,0.05731978,-0.08038301,0.047906425,-0.030007858,-0.036846153,0.061865706,-0.049822796,0.0037274838,-0.0065919897,-0.03283203,-0.0009767853,0.07956497,-0.034670733,-0.020307679,0.005681171,0.0055590016,0.024775965,0.03965166,-0.014769853,-0.012365479,0.014648819,-0.01276768,0.07805812,0.013132805,-0.073200084,0.06146577,0.014116633,0.008238451,-0.007988953,-0.037393432,0.0033550041,-0.027729856,0.06136802,-0.045651644,-0.00045876866,-0.06448912,0.03373305,0.009349263,-0.052026924,0.082740754,-0.05351347,-0.054537084,-0.014924217,0.0094457725,0.016414357,-0.02404483,-0.02229687,-0.045005716,0.039907414,0.030284217,0.03329845,-0.013159425,0.051776607,-0.051389694,0.0667639,0.010356204,-0.004976946,0.059956744,0.0032638046,-0.07194973,0.014846277,0.009327625,-0.00041885438,-0