insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('8820997','utility','8820997','US','9/2/2014','A light source device includes: a light guide plate having a first internal reflection face and a second internal reflection face, and having one or more side faces; one or more first light sources applying first illumination light into the light guide plate; and a second light source disposed to face a surface, of the light guide plate, corresponding to the second internal reflection face, the second light source externally applying second illumination light to the second internal reflection face. One or both of the first and second internal reflection faces each have scattering regions allowing the first illumination light from the first light source to be scattered and to exit from the first internal reflection face to outside the light guide plate, each of the scattering regions being provided with one or more pass-through regions each allowing the second illumination light from the second light source to pass therethrough.','Light source device and display','B2',11,'ipg140902.xml',0,'[-0.01821513,-0.029672151,0.06269524,-0.03135911,-0.030212576,0.06369709,0.0028677338,-0.0037360594,0.070174985,-0.050124608,0.01079165,-0.0114364885,0.037535753,-0.029551765,-0.009899705,-0.0048326203,-0.0042589824,-0.060057927,-0.0030925921,-0.0355957,-0.0055039227,-0.04291341,-0.07020167,0.019791793,0.08138967,-0.09603321,0.035583515,-0.046896093,-0.04707281,0.075870305,0.0077326866,-0.03349326,0.03802092,-0.0016610167,-0.018382376,0.004091259,0.039086517,0.0049490524,0.059802778,0.017160067,0.08332703,-0.030637292,-0.00933211,-0.054806538,-0.037704498,0.036375538,-0.050760992,0.03755611,0.019978598,-0.03136835,0.030991472,0.052567493,-0.01619502,-0.044270262,0.026702328,0.06140236,0.030931335,0.033162806,0.005062833,-0.009947801,0.0516035,-0.06568383,0.029567204,0.021318307,-0.0831047,0.033812