insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6230281','utility','6230281','US','5/8/2001','A method and apparatus for providing back-up management of a network element in a multi-tiered network management system. Network elements have a primary element manager responsible for managing communications with that network element and a secondary element manager that can be at a geographically remote location responsible for assuming control of communications with the network element should the primary element manager become unable to do so.','Geographic redundancy protection method and apparatus for a communications network','A',52,'pftaps20010508_wk19.zip',0,'[-0.049816865,0.009518429,-0.024183497,0.011835951,0.0144787105,-0.016733296,-0.004104817,-0.023931079,0.023546198,-0.027308954,-0.015487198,-0.047769967,0.06369155,-0.049422197,0.06407291,-0.035902843,0.040469438,-0.024725799,-0.00809528,-0.06427305,0.04627763,-0.020729043,-0.07204821,-0.0030929104,-0.003969796,-0.092251085,0.027045969,-0.001875697,-0.068386294,-0.00437607,0.04646172,-0.011714254,0.10737406,-0.014015792,-0.0075533334,0.006562594,0.039803352,-0.0006325283,0.022198481,-0.04590029,0.009266852,0.030526703,0.03425422,-0.039731372,0.026363678,0.029379703,-0.050471384,0.026144389,0.025571825,-0.025004454,0.027984746,0.011368688,0.012108904,0.005414115,-0.009578969,0.019978654,0.0133465035,0.03566703,0.028993022,0.009416522,-0.039977677,-0.049176507,-0.0041245506,-0.024103204,-0.06725234,0.07967503,-0.00043212884,0.040892947,0.014642249,-0.021487763,0.03784104,-0.091536835,0.058004506,-0.050677553,-0.056618173,0.012987987,0.03921227,-0.043467198,-0.035606824,0.025277099,-0.048509452,-0.005547558,-0.030888753,0.035568036,0.05209635,-0.047628388,-0.03527124,-0.0498192,-0.0186313,-0.010583195,0.040866464,0.015580628,0.053622447,0.0016530989,0.050316695,0.044532858,-0.03822059,0.11684649,-0.017599108,0.034293298,0