insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6230625','utility','6230625','US','5/15/2001','A disarmable firing module with a firing module housing having an opening therein; a detonator holder received in the firing module housing via the opening in the firing module housing, the detonator holder including a cavity therein; a detonator disposed in the cavity of the detonator holder; and a detonator electronics assembly housed within the firing module housing. The detonator holder is removably secured within the housing which allows the detonator to be separated from the detonator electronics assembly to disarm the firing module.','Disarmable firing module','A',11,'pftaps20010515_wk20.zip',0,'[-0.053795625,-0.0396255,0.026914418,-0.04576559,0.011567826,0.06622706,0.016223226,-0.012880186,0.013743673,-0.013267949,-0.030888276,-0.032980993,0.008009476,-0.07056641,0.028471608,0.0070132734,0.058227118,-0.06734112,0.046884947,-0.042169813,-0.013560254,-0.077659585,-0.06883344,0.014284312,0.022048797,-0.09342707,0.039846502,-0.02245392,-0.03848509,0.09354663,-0.024106322,-0.0667606,0.08747536,0.022761822,-0.02431176,0.015349475,-0.0044225887,0.053803913,-0.0012009516,-0.0021057976,0.018865036,-0.02911427,0.05212382,-0.014688934,0.033858884,0.0010030341,-0.039515376,0.054129384,0.06950792,-0.02140424,0.048634667,0.08067901,-0.016073659,-0.059222184,0.03991328,-0.0058634807,0.016949687,0.040961765,0.004895458,0.0590148,0.0132941315,-0.028801851,-0.007849688,-0.0047466806,-0.033867218,0.08955464,0.06908052,0.0074774963,-0.03468608,-0.051223446,-0.024949512,-0.039836608,0.002542117,-0.047452316,-0.00095867505,0.057596628,-0.014467331,0.025607584,0.00415967,0.06560818,-0.087249,-0.027574109,-0.04014239,0.03273875,-0.010644708,-0.019318774,-0.01911887,-0.014865413,0.011678713,0.0392716,-0.0025414904,0.0009633598,0.021677831,-0.0067303316,0.024503393,-0.016626136,-0.004030289,0.06762