insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6232688','utility','6232688','US','5/15/2001','The present invention contemplates an internally reinforced high-speed magnetic thrust disk. In one embodiment the internally reinforced composite thrust disk comprises a plurality of high strength fibers coupled together by a soft magnetic alloy. Further, in one aspect the disk having internally reinforced zones for controlling bore growth and counteracting forces associated with the reaction between the stator and the rotor of the electromagnetic thrust bearing system.','High speed magnetic thrust disk','A',22,'pftaps20010515_wk20.zip',0,'[-0.048242494,0.0344511,0.008262453,-0.02694879,0.002225191,0.04239345,-0.050442323,-0.019365577,0.051152557,-0.01571305,-0.042795654,0.0284055,0.078073904,-0.09834614,0.04829047,-0.014793549,0.02977543,-0.05362444,-0.028783668,-0.023474049,-0.0035683801,-0.04365128,-0.03775756,0.035921812,0.002830718,-0.077977456,0.03051464,0.0126893325,-0.0469762,0.07249384,-0.0021005606,0.0041904645,0.032309026,-0.0132914595,0.02444156,-0.012252261,0.022693463,-0.024780167,8.98691e-05,0.009814895,0.035833173,-0.061447397,0.031669226,-0.010105682,-0.02195526,0.019820796,-0.028635917,0.050343808,0.06543196,-0.050558336,-0.010984056,0.011574588,-0.0046651913,-0.02458533,0.060734633,0.058516134,0.015540482,0.0076341927,0.019152272,-0.020694615,-0.019439047,-0.032786667,0.005133053,-0.027454194,-0.049601194,0.034236893,0.026207026,-0.010541355,0.04930231,-0.024001757,-0.010535938,-0.026541786,0.01499737,-0.068071775,-0.056193497,0.025340687,0.023025507,0.011435847,0.0076829465,0.0647202,-0.06768977,-0.012547738,-0.017494109,-0.00015257765,0.008199623,-0.024638118,0.007234876,-0.01204464,0.01232458,0.053710714,0.011343023,-0.007177884,0.06721771,-0.010638017,0.026887903,0.025278091,0.06643954,0.060702212,-0.004516987,-0.00040312595,0.037192307,-0.009419709,-0.0029