insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6238487','utility','6238487','US','5/29/2001','A method for determining wafer cleanliness by fluorometric monitoring of the impurities in the semiconductor chip wafer rinse solution. A clean chip is indicated by a leveling off of increased concentration of impurities as the rinsing of the chip progresses. A method for optimizing reuse or recyling of the water discharged from the rinse process which accurately measures the contaminants in that water.','Method for improving the efficiency of semiconductor chip production','A',1,'pftaps20010529_wk22.zip',0,'[-0.06460086,-0.055675704,0.02339457,-0.014347156,0.016986424,0.049478326,-0.0044941865,0.05438116,0.03252411,-0.03738318,0.0022819878,-0.031189285,0.007034143,-0.030531004,0.041237995,-0.0165359,0.020922538,-0.057094116,-0.017123552,-0.0063901586,0.023288101,-0.05422495,-0.0034374555,0.04830824,0.060563076,-0.08597861,-0.009976129,-0.027173039,-0.1062207,0.055669878,0.032289967,-0.013374104,0.014798299,-0.014794791,0.014314422,-0.027828831,0.006037317,0.031538147,0.007832913,0.030477822,0.08399789,-0.044994067,0.022096327,-0.03165879,-0.016660767,0.0093370965,-0.029997554,0.035298977,0.00697268,-0.09351662,-0.014486946,0.018253962,-5.8113346e-05,-0.037012078,0.047002546,0.03536579,0.024355434,0.05178474,0.010412153,0.03488072,0.020125108,-0.037759792,-0.0051357523,0.0237731,-0.07178617,0.07715664,0.061686326,0.014353716,-0.00404471,-0.06590454,-0.0465594,-0.0036849116,0.048827887,-0.038265325,0.0022438327,-0.036049258,0.006307454,-0.0014129579,-0.034426495,0.06234779,-0.014449076,-0.04928741,-0.057903845,0.028529912,0.051076286,0.013957577,-0.057418853,-0.06859478,-0.024831986,0.049023222,-0.028517481,-0.03123394,0.044951923,0.013868381,0.034722313,0.0471134,0.02086175,0.07126795,0.0131786475,0.024349114,-0.014912218,0.05774021,0.0020527858,-0.028348703,-0.022071017,0.0303633