insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6250768','utility','6250768','US','6/26/2001','A lighting apparatus for a model lighthouse provides a lighting effect similar to that of a commercial lighthouse. In one embodiment a lamp is rotationally driven. In another embodiment a lighting means for extending a stationary lamp is taught so as to accommodate various size lighthouse models. In a still further embodiment, a combination of rotational and extension features are provided including a set of exterior wipers mounted in electrical contact with slip rings onto a rotating boom for delivery of power to a lamp.','Lighting apparatus for a model lighthouse','A',13,'pftaps20010626_wk26.zip',0,'[-0.024983203,0.0036006512,-0.009656562,-0.0026534493,0.019147493,0.021274379,-0.05106187,0.009282265,0.031451147,-0.036322124,-0.0013775135,-0.016475232,0.09593276,-0.09119485,0.012364126,0.05626538,0.0033452353,-0.028391317,-0.015414472,-0.026283937,0.023625243,-0.03872072,-0.061186537,0.029020792,0.058139663,-0.108671315,0.0135439,-0.0129987225,-0.058926668,0.02050794,-0.021464504,-0.047821697,0.042828254,-0.0007186015,-0.019020151,-0.048232213,-0.0021724745,0.040599007,-0.008465227,-0.018612579,0.07219783,-0.05199158,-0.028428061,-0.07225087,-0.013464313,0.0011170277,-0.06656991,0.032229822,0.0475177,-0.036284965,0.02923214,0.0269589,-0.033717144,-0.05323675,0.023683287,0.09804543,0.01258908,0.027558254,-0.0014663499,0.040570408,0.048881896,-0.01274084,0.04972904,0.003942399,-0.021594774,0.07807729,-0.002427351,0.0041245995,-0.026360653,-0.01007962,-0.042341042,-0.031611435,0.0010887363,-0.10784931,0.009523043,0.0029321876,0.019143658,-0.04327688,-0.03229118,0.05690273,-0.008332223,-0.0066453815,-0.006761424,-0.04846385,-0.025430016,-0.023063242,0.02810137,-0.005341994,-0.021967886,0.0031459716,0.03912651,-0.084139444,-0.019775884,0.0057119713,0.046850447,0.056814414,0.019765949,