insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6258496','utility','6258496','US','7/10/2001','A stretched mask having a high tensile strength and favorable high-temperature creep properties and free from tape twist, and a material for the stretched mask. A low-carbon steel sheet containing 70 ppm to 170 ppm of nitrogen on a weight basis is heat-treated at a temperature at which recrystallization does not take place. The heat-treated material is provided with a resist pattern for forming apertures and subjected to etching to form apertures.','Stretched mask for color picture tube','A',2,'pftaps20010710_wk28.zip',0,'[-0.013464079,0.036008574,0.030807348,-0.047106795,0.0057856906,0.07633146,-0.022352219,-0.02299839,0.026670765,-0.06962899,0.029521802,-0.015135037,0.047422864,-0.07910359,0.020564329,-0.032046802,0.054702517,-0.102878496,-0.0021019222,-0.032869603,0.03435915,-0.079387344,-0.0030150507,0.014534304,-0.013029813,-0.066893935,0.009583834,0.0027440109,-0.012152689,0.020620614,-0.038459376,-0.05219621,0.061789904,-0.016997905,0.026973112,-0.053017374,0.031073896,-0.031559605,0.06222254,-0.00980628,0.010205762,-0.028292455,0.009831783,0.01793846,-0.017523421,0.03692776,-0.006540203,-0.013196101,0.090666845,-0.0021598304,-0.014833432,0.075415194,0.00095998135,-0.031173157,0.018340912,0.033619437,0.025191698,0.094711386,-0.0180382,-0.041714475,0.023103867,-0.036025833,0.00894457,0.056493893,-0.031270456,0.07264131,0.012166234,0.06671478,0.010701697,-0.046773806,-0.029065223,0.008494421,0.03536119,0.03141519,0.00563467,0.03756496,0.00059789437,0.033608593,0.012277215,0.044478904,-0.05712855,-0.029688366,-0.0026736027,-0.038929813,0.06723951,-0.068629354,0.015509168,0.0026412539,0.007499505,0.008393366,0.026687702,-0.06582697,0.033685718,0.022222191,0.014337418,-0.005702671,0.017438749,0.049707513,0.033647586,0.027803855,0.042857148,0.034605473,-0.026296457,-0.0063640145,