insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6258827','utility','6258827','US','7/10/2001','This invention relates to a method of treating Parkinsons Disease whereby a mammal suffering from Parkinsons Disease is treated with a combination of a forebrain selective NMDA antagonist and a compound which is capable of increasing the excitatory feedback from the ventral lateral nucleus of the thalamus into the cortex. This invention also relates to pharmaceutical compositions containing the synergistic combination.','Combinations for the treatment of parkinsonism containing selective NMDA antagonists','A',5,'pftaps20010710_wk28.zip',0,'[-0.018486457,-0.009907934,-0.0019252598,-0.07394586,0.029194856,0.038772937,-5.641103e-05,0.007331238,0.07009852,-0.031554352,-0.04570128,0.038785707,0.01977664,-0.11048257,0.054685675,-0.005995134,-0.016490245,0.024675699,0.053472728,0.0037845457,0.021917537,-0.04350956,-0.041485522,0.025919002,-0.011554668,-0.0054750135,0.018865088,-0.0016287835,-0.026785206,0.030877687,0.015177568,0.012690997,0.0743781,-0.04057167,-0.017099813,0.012272695,-0.007389817,0.0010423583,0.016092563,0.0302249,0.011976306,-0.02493452,-0.05651743,-0.009411796,0.0082705645,0.054266326,-0.0812915,0.017387616,0.037425134,0.040802978,0.009879758,0.030315358,-0.0055881906,0.07779118,0.07391279,0.032698825,0.0049378183,0.05464114,0.001397074,0.0521197,-0.00478857,-0.09270734,0.045680176,0.03804806,0.02966688,0.052949473,0.07289712,0.04761193,0.029680377,-0.013343554,-0.022724459,-0.01063298,0.03302378,-0.07974963,-0.04643542,0.018791558,0.0017441608,0.03268564,0.030786091,0.049067475,-0.06935919,-0.10090173,-0.06861072,-0.023537155,-0.009176272,-0.064101286,0.007581401,-0.04880063,0.010983379,0.037842922,0.011617896,-0.0032778995,0.021622693,-0.03800796,0.029373458,0.05748046,-0.0068412833,0.10384955,0.02805792,-0.047315523,-0.017301092,0.022929965,0.030291595,0.014804075,