insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6259212','utility','6259212','US','7/10/2001','A plasma display panel includes front and rear substrates facing each other, common and scanning electrodes on the bottom surface of the front substrate, spaced apart from and parallel to each other, a first dielectric layer on the bottom surface of the front substrate embedding the common and scanning electrodes, address electrodes on the rear substrate orthogonal to the common and scanning electrodes, a second dielectric layer on the top surface of the rear substrate embedding the address electrodes, partition walls defining discharge spaces, each partition wall including a white partition wall on the top surface of the second dielectric layer, and an auxiliary partition wall on the top surface of the white partition wall and reflecting only light in a wavelength range of 420-550 nanometers, and red, green, and blue light-producing phosphor layers on the second dielectric layer and between the partition walls.','Plasma display panel','A',3,'pftaps20010710_wk28.zip',0,'[-0.03420003,-0.035455815,0.035246056,-0.021273531,-0.047105327,0.041936297,0.028061705,0.034315366,0.04388587,0.004875908,-0.041090254,0.015931416,0.008196946,-0.052618783,-0.0013359281,0.016054973,0.022056064,-0.05683808,-0.011536854,-0.019274715,0.01551324,-0.06673851,-0.098809235,0.0017206391,0.04146568,-0.095099136,-0.0029161603,-0.0025898262,-0.030353341,0.048228387,0.106589764,-0.041690156,0.055997923,0.004971301,0.014351308,-0.0080891345,0.030570926,0.019015316,0.03462255,-0.024763655,0.055137977,-0.021247882,0.021499807,-0.03943725,-0.0549587,0.053795103,-0.027046992,0.020596694,0.030342767,-0.04538595,0.0038838035,0.10127633,-0.05918821,-0.029352384,0.009445849,-0.026341755,0.024464907,0.05665987,-0.03207705,0.019681476,-0.032686867,0.023439392,-0.0010165252,0.028991088,-0.094376676,0.041069273,0.0478,0.0