insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('6261235','utility','6261235','US','7/17/2001','The present invention relates to a diagnosis apparatus for analyzing arterial pulse waves comprising a database 26 in which is stored data showing the relationship between data representing a pulse wave of a living body and teaching data representing conditions of the living body; and a micro-computer 21 for outputting teaching data corresponding to the pulse wave detected from the living body in the teaching data on the basis of the pulse wave detected from the living body and the stored data inside database 26. As a result, it becomes possible to perform diagnoses equivalent to a skilled doctor.','Diagnostic apparatus for analyzing arterial pulse waves','A',17,'pftaps20010717_wk29.zip',0,'[-0.018666185,0.005379403,0.013849398,-0.011965484,-0.035189606,0.05164652,0.0061237123,-0.033870813,-0.01147569,-0.0429606,-0.021717386,0.0030742316,0.005101926,-0.06487707,0.048026644,-0.017701175,0.0077498206,-0.09742375,-0.026060162,-0.011640026,0.01796812,-0.025130624,-0.09127826,-0.01931787,0.007674699,-0.0726939,0.029805435,-0.038392678,-0.061274398,0.049406387,0.001756948,-0.019526495,0.024351073,0.01560645,0.03703955,-0.0029292041,-0.010462596,0.009593077,0.06531958,-0.037076965,0.026865508,-0.026681673,-0.02033899,-0.06218658,-0.02665839,0.026684456,-0.06413679,-0.013893531,-0.05429051,-0.015276886,-0.025102334,0.027584381,0.00037294487,-0.027469624,0.022455381,0.021855367,0.02414252,0.014143872,-0.003184197,0.04338695,0.003074167,-0.015194746,0.036151264,0.015409428,-0.0445041,0.10475747,0.0095773535,0.046282407,0.036040187,-0.026481222,-0.05396024,0.029151043,0.003128756,0.003835922,-0.014287528,-0.025603464,-0.028990269,0.007001985,0.02446459,0.019878771,-0.0519336,-0.02649126,-0.11047685,0.048654452,0.083423376,-0.003044863,-0.0069493223,0.025828186,-0.004216419,-0.036183227,0.106