insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7481632','utility','7481632','US','1/27/2009','A scroll compressor is provided with an orifice plug inserted into an oil passage. The plug has an opening which is positioned to restrict the flow of oil through the passage, and in particular at higher speeds. The opening is formed at an outer periphery of the plug, and may be positioned at a location spaced furthest from the center of rotation of the shaft.','Scroll compressor with an oil passage plug to limit oil flow','B1',5,'ipg090127.xml',0,'[-0.01534857,0.030468315,0.0026236486,-0.02860805,-0.008358146,0.046591327,0.013118068,-0.030280676,0.007425076,-0.04293359,-0.10735689,-0.004738094,0.068010606,-0.090674415,-0.02131519,0.028481845,0.032429636,-0.05444594,-0.022346484,-0.010434798,0.058616,-0.02375538,-0.015943345,0.028446252,0.04597807,-0.07588515,-0.03372363,-0.018811284,-0.069817886,0.04053131,0.0457307,-0.053329084,0.083225325,0.017866457,0.0023566976,-0.0122023085,0.021831606,0.033088557,-0.013142917,0.0066642817,0.051229052,-0.07197425,0.019303469,-0.024159012,-0.061282475,0.04856912,-0.023299264,0.009364488,0.0780772,-0.0796002,-0.029655294,0.0036439982,-0.013034839,-0.055700537,0.013809904,0.056487653,0.029477129,-0.0059635527,0.004167273,0.04353257,-0.042356875,-0.022925097,-0.037374035,-0.021657612,-0.062079523,0.022771735,-0.00244651,0.019640096,0.02798392,-0.004083855,-0.009524594,-0.018542916,0.029995471,-0.018004447,-0.025988849,0.014809528,0.011419307,0.05155744,-0.032909494,0.061737843,0.0018889551,-0.0040209144,-0.06234933,-0.0009740091,0.028884647,-0.03767688,-0.0165857,-0.029634751,0.00094898825,0.014251797,-0.017690273,-0.0061461963,0.03460157,-0.054217763,0.018074702,0.030096471,0.008142626,0.06448067,0.0024665387,0.025407253,0.03292671,0.04354698,-0.04876458,0.0048386822,0.03344371,0.031032471,0.054127578,0.006149511,0.08510167,-0.02436676,0.003243