insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7488292','utility','7488292','US','2/10/2009','A blood-vessel detecting device includes a partially-deforming device which can be inserted into the body cavity so as to come into contact with the tissue surface in order to deform a part of the tissue surface so that turbulence is generated in a blood flow within blood vessels extending underneath the tissue surface, thereby enabling detection of the presence or absence of blood vessels underneath the tissue surface. Turbulent sound due to the turbulence generated at a part of the tissue surface deformed by the partially-deforming device is converted into electric signals by a converting device, following which the electric signals are subjected to signal processing such as amplification and so forth by a signal processing device.','Blood vessel detection device','B2',28,'ipg090210.xml',0,'[0.015883336,0.007792825,0.03960303,-0.024090972,-0.022044376,0.063201234,0.0076718344,-0.009839696,0.026167404,-0.03314192,-0.0032817393,-0.0061041773,0.048361618,-0.0695202,0.0028620013,-0.015967123,0.049691778,-0.09416458,-0.036414683,-0.047627475,-0.064243205,-0.050222326,-0.042923883,0.017722424,0.051459827,-0.08229194,0.0010156442,-0.07145936,-0.041671343,0.022533245,-0.032358233,-0.071258724,0.017723206,0.025798246,0.031067792,-0.0047393464,0.008178512,0.011962241,0.036618613,0.013565214,0.015664011,-0.017307606,0.018693967,-0.029833935,-0.047241062,0.018770935,-0.0019052504,0.030984487,-0.0066582756,-0.034043916,-0.004419717,0.019835025,0.0212712,-0.068480566,0.037427653,0.045361586,0.055222496,0.019074982,-0.017507046,-0.00523122,0.011142414,-0.023908013,0.02252704,0.016047506,-0.07141064,0.06669099,0.038730424,0.075767055,0.03387243,-0.039222006,0.009084847,0.0036742804,0.036614586,-0.0026287336,-0.039149925,-0.013297127,0.030332524,0.01988641,0.00499888,0.03968211,-0.020853512,-0.0