insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7488572','utility','7488572','US','2/10/2009','An image formation method comprising exposing a photothermographic material 10 having an image-forming layer and a back layer with a light having a wavelength of 700-850 nm and subjecting it to development in a heat development apparatus provided with a preheating section A, a heat development section B and a gradual cooling section C, wherein the photothermographic material 10 has at least one coated layer obtained by applying a coating solution containing 20 weight % or more of an organic solvent, and the heat development section B is provided with heating members 15 on image-forming layer side 10a and back layer side 10b and transportation rollers only on the image-forming layer side 10a with respect to the photothermographic material 10 to be transported in the apparatus. There is provided an image formation method utilizing a photothermographic material, which can form images showing less generation of density unevenness, high contrast and high maximum density without causing physical deformation.','Image formation method','B2',26,'ipg090210.xml',0,'[-0.026906097,-0.0042433105,0.060737103,-0.029194646,-0.03354733,0.06970447,-0.03597954,0.0038859092,0.07234649,-0.011316769,-0.0021498613,-0.008870047,0.02363145,-0.06465388,0.04387097,-0.043258883,0.058587726,-0.07775416,-0.01314309,0.004045692,0.033939794,-0.065628774,-0.006722605,0.02501159,-0.0335185,-0.05220916,-0.012803621,-0.026602034,-0.036113042,0.050921455,-0.041351788,-0.038214847,0.10625019,-0.034159,0.023919646,-0.017013457,0.019750688,-0.024673443,0.06568137,0.007934495,0.09017331,-0.029838,0.032466557,-0.08121838,-0.055441163,0.06695302,-0.032931887,-0.0032639438,0.03221302,-0.006883033,0.018795265,0.089725316,0.003913109,0.0032030756,-0.0056089545,-0.004711639,0.015067699,0.07545352,-0.011343424,-0.0032996621,0.04