insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7490568','utility','7490568','US','2/17/2009','A bearded needle comprises a needle shank whose tip is shaped into a thin shank portion by tapering down the thickness of the needle shank. The thin shank portion has a conical projection portion at the extremity thereof. The conical projection portion has a hooking tip portion to form a hooking portion at the tip of the needle shank. The hooking portion has a substantially U-shaped bottom portion that hooks and holds a thread, and includes sloping surfaces each inclining toward an outer edge of the hooking tip portion. The sloping surfaces each extend from the bottom portion over both the conical projection portion and the hooking tip portion.','Bearded Needle','B2',11,'ipg090217.xml',0,'[-0.04586858,0.008060279,0.039359245,-0.0023532796,0.04022779,0.044498224,0.028177455,-0.04618615,0.004212838,-0.061240643,-0.0021530623,-0.019391764,0.0484467,-0.05917793,0.003544806,-0.004201022,0.030813886,-0.06950639,-0.009653497,-0.04693247,0.033511825,-0.005491531,0.009354218,-0.0110899275,0.065689616,-0.058476493,0.013195527,-0.04406795,-0.04307333,0.08217369,0.010182349,0.0069152582,0.02914339,0.07578233,0.00010023166,-0.024787277,0.02019198,-0.008360176,0.004391746,0.039362125,0.053723928,-0.042305805,-0.0137670105,-0.047043003,0.0056178384,0.013178651,-0.03819937,0.03660087,-0.016361753,-0.05535527,0.024147298,0.03310479,-0.013679982,-0.013967447,0.058517754,0.042309638,0.02932509,0.017396394,-0.0374642,0.0040651825,0.0044698142,-0.017515387,-0.018952142,-0.005570914,-0.047086727,0.013394485,0.038350046,0.044480532,0.03571345,0.0068827225,0.03627529,-0.040994078,-0.008650997,-0.01590231,-0.019557498,-0.032635745,0.004225892,0.05586737,0.0031371035,0.032180265,-0.09917498,-0.03474808,-0.06403036,-0.08035203,0.05920095,-0.04296494,0.00015492612,-0.012942834,-0.00795893,-0.005920939,0.0240