insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7493505','utility','7493505','US','2/17/2009','A low power system is disclosed for working in conjunction with a digital circuit that is disposed between positive and negative terminals. The system includes an internal voltage generator for increasing, for at least a first portion of the digital circuit, a voltage difference between the at least a first portion of the digital circuit and the voltage on at least one of the positive and negative terminals during a low power mode of operation. This allows the voltage across the at least first portion of the digital circuit to be less than the full voltage across the positive and negative terminals.','MCU with low power mode of operation','B2',11,'ipg090217.xml',0,'[0.043895673,-0.02229239,0.0020726626,-0.027089568,0.006230242,-0.023434274,0.028276397,0.020062981,0.020600392,-0.054664485,-0.049984533,-0.015917227,0.0423082,-0.08041411,0.047210705,0.01513789,-0.003592962,-0.017626591,-0.03838802,0.0057169725,0.019388268,-0.094984494,-0.06731073,0.03870011,0.04165759,-0.11442273,0.050540306,-0.011334309,-0.055439245,0.083465554,-0.018180035,-0.051669307,0.021570608,0.0077384496,0.022582993,-0.04387004,-0.023216512,-0.016974544,-0.023084184,-0.050787255,0.0037473906,-0.05356447,-0.025947649,-0.07671708,-0.049325503,0.040474124,-0.051259965,0.030042889,0.016168563,-0.00978171,-0.047661494,0.019614872,-0.0017611617,-0.04048269,-0.006873781,0.046700392,0.013032475,0.04061572,0.0067693754,0.06999022,-0.052863978,-0.10942757,0.022488248,0.005048177,-0.01537019,0.0763838,0.041619413,-0.01049168,-0.01588865,0.0031793518,-0.0029447963,-0.043536372,0.06412182,-0.058078963,0.029038534,-0.019210136,-0.016096668,-0.004090553,0.019195408,0.084350176,-0.027325291,-0.03938645,-0.06620346,-0.03882752,0.03609867,-0.044103097,-0.050737087,0.00011678864,-0.00787182,-0.024706742,0.0015932927,-0.02716328