insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7167074','utility','7167074','US','1/23/2007','Method and apparatus are provided for fabricating a planar transformer assembly for use in an implantable medical device. The planar transformer assembly includes a board, a first core, and a second core. The board has a first side, a second side, and an embedded winding, wherein the embedded winding includes a primary winding and a secondary winding and is at least partially embedded in the board between the first and second sides.','Integrated planar flyback transformer','B2',9,'ipg070123.xml',0,'[-0.019219669,-0.003203198,0.031146353,-0.04028826,0.050025303,0.020319464,-0.10645659,0.0035967669,0.029667184,0.03623987,-0.009497202,-0.037569664,0.020154823,-0.09569615,0.05634896,0.023912845,0.04363292,-0.08226912,-0.012139266,-0.009014727,-0.023090389,-0.04920977,-0.07348684,0.05428312,0.0607063,-0.070043735,0.007877458,-0.020540357,-0.009579471,0.031998392,-0.028435467,-0.03225395,0.02131946,-0.01810672,0.019022131,-0.032334104,0.0072390903,-0.008975685,-0.0012830389,0.007501377,0.02836968,0.006041973,0.03284855,-0.028034152,-0.032442942,0.058854513,-0.042114813,0.062019646,0.013422332,0.040967017,0.04983777,0.050242137,0.010729985,-0.07507083,0.024751218,0.07425157,0.017533565,0.05035573,0.019443389,0.03955074,0.011254421,-0.01514658,-0.0068317614,0.000957293,-0.017721897,0.07601298,0.05049796,0.025012588,0.058744933,0.018626055,-0.03715399,-0.06620548,0.05050681,-0.020811334,0.00364195,0.0068874937,0.023653362,-0.0069024996,0.00675069,0.06063321,-0.030525051,-0.04012545,-0.04266775,-0.045945212,-0.019156113,0.024852244,-0.044881344,-0.021588875,0.044856858,0.0362815,0.029139727,-0.026051184,0.008111436,-0.039493788,-0.00858433,-0.004602351,0.00044686717,0.062213026,-0.062081307,-0.0063115535,0.054698836,0.0032481176,-0.013811883,-0.018357085,0.022668974,0.054145817,-0.029776134