insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7500738','utility','7500738','US','3/10/2009','An ink cartridge includes a container in which ink is accommodated, an ink supply hole which is formed in the container so as to be open in an outer surface of the container, a plurality of atmosphere communication holes which are formed in the container so as to be open in the outer surface of the container, and a strip member which is removable stuck to the outer surface of the container to seal the ink supply hole and the plurality of atmosphere communication holes. The ink supply hole is sealed by a longitudinally intermediate portion of the strip member, and at least one of the plurality of atmosphere communication holes is sealed by a portion of the strip member which extends from the longitudinally intermediate portion toward one of longitudinally opposite ends thereof while at least one of the plurality of atmosphere communication holes is sealed by a portion of the strip member which extends from the longitudinally intermediate portion toward the other of the longitudinally opposite ends.','Ink cartridge','B2',17,'ipg090310.xml',0,'[-0.033266846,-0.003706625,0.07205145,-0.027522694,0.004867553,0.010822851,-0.019378193,-0.014750607,0.02897833,-0.022190025,-0.017132314,-0.038061004,0.0363811,-0.056819264,0.03769527,-0.00922659,0.04836241,-0.028184678,0.012029228,-0.015746681,0.012219386,-0.046703152,-0.0213166,0.030062653,0.05595713,-0.12750548,-0.01935728,-0.02812265,-0.040064096,0.0861659,-0.04562146,-0.072266705,0.06856895,0.019629419,-0.024183564,-0.011979025,0.046692796,-0.01949609,-0.01770784,0.02110571,0.045968525,-0.04793847,0.02113686,-0.042755514,-0.058754433,0.0102245165,-0.045328718,0.038273137,0.023803081,-0.10821293,0.015603294,0.059069064,-0.037410054,-0.059291888,0.0020307803,-0.0052024797,0.067271546,0.07760229,-0.017264474,0.010471138,-0.044286113,-0.02911