insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7510811','utility','7510811','US','3/31/2009','A toner for developing an electrostatic image of the present invention contains toner particles obtained by forming coagulated particles by mixing a resin particle dispersion solution containing dispersed resin particles and a coloring agent dispersion solution containing dispersed coloring agent particles and fusing the coagulated particles by heating them and is characterized in that at least the surfaces of the toner particles have a chemical structure formed by reaction with a compound having a carbodiimido group. The invention also provides a resin particle dispersion solution to be used for the production of toner.','Toner for developing electrostatic image and resin particle disperision solution for toner for developing electrostatic image','B2',20,'ipg090331.xml',0,'[-0.027674694,-0.019724332,0.030812804,-0.019905955,0.041835595,0.12162182,-0.043075908,0.049141344,0.013219613,-0.03790392,-0.028844226,-0.008472546,-0.024198625,-0.04532601,0.031831294,0.021321846,0.04728315,-0.07414874,0.03139577,0.013138744,0.031188935,-0.064097874,0.0050510927,0.003345446,0.004199912,-0.058094334,0.009024552,-0.03383654,-0.02973178,0.069629215,0.0035474855,0.0029695416,0.12076627,-0.0038408195,0.012301379,-0.019988608,0.03991972,-0.050591767,0.045084234,0.026602073,0.089677945,-0.06182042,-0.0076088407,-0.006200654,-0.021642754,0.0066710613,0.0034769885,-0.017969804,0.06963834,-0.022347493,-0.03784941,0.046370573,-0.02286527,-0.05116154,0.06079192,0.007207653,0.04272447,0.07312756,-0.016867107,0.04680128,-0.010201497,-0.04196545,0.00047016627,0.03197262,-0.023761,0.02922852,0.0061436454,-0.004598425,0.038263857,-0.0027181772,0.0035220208,0.023860259,-0.02315375,-0.041924704,0.025934586,-0.04421788,0.029916557,0.050332997,0.015842754,0.103399254,-0.060062088,-0.043109488,-0.06003843,-0.0356