insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7514335','utility','7514335','US','4/7/2009','A method of manufacturing a semiconductor device includes providing a base plate; mounting a plurality of semiconductor chips, the plural semiconductor chips being mounted apart from each other; forming an insulating film on an upper surface of the base; forming a plurality of pairs of re-wirings on the insulating film, each of the re-wirings being connected to a connection pad of any of the semiconductor chips the insulating film formed on the periphery of the semiconductor chip, and the re-wiring having a pad portion arranged in the region of the insulating film.','Semiconductor device and method of manufacturing the same','B2',18,'ipg090407.xml',0,'[-0.024907565,-0.012692001,0.029957855,-0.025833244,-0.025202645,0.048615724,-0.02844543,0.0195039,0.03057814,-0.016617235,0.0015318788,-0.0058376705,0.018672362,-0.050329294,0.015409193,-0.011263601,0.05699801,-0.07760631,-0.009527663,-0.020740325,0.023017328,-0.06446118,-0.03735095,0.030002555,0.058403425,-0.11614548,-0.009389722,-0.0019414318,-0.04792948,0.06864409,0.0026998206,-0.03800331,0.036136027,-0.030812649,-0.014314812,-0.050888587,0.01858768,0.006244125,0.018713068,-0.01132131,0.05044376,-0.026571415,0.005869424,-0.03944299,-0.03244526,0.03350581,-0.06972702,0.07166568,0.009940155,-0.01811014,0.005461748,0.05474471,-0.041543614,-0.052349366,0.05862199,0.042728852,0.033930823,0.1068509,-0.033953667,0.0514642,0.0027187283,-0.045014147,-0.02554904,0.0075678863,-0.055391967,0.033900365,-0.0005875342,0.004975003,-0.020272251,0.006208197,-0.03320744,-0.025685173,0.018591693,-0.06955059,0.020340363,-0.04481192,-0.0073389746,-0.022388134,-0.025552792,0.08439073,-0.056750517,-0.03695163,-0.055095103,0.007419679,0.03157018,0.015700629,-0.051025093,0.021150425,0.022425048,0.05883465,0.03260927,-0.027499046,0.015225428,0.00058737217,0