insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7162161','utility','7162161','US','1/9/2007','A section of tapered optical fiber is provided to protect optical components from catastrophic damage that may propagate within an optical route. The tapered section functions as a fuse to arrest the propagation of optical power induced damage by leaking optical power from a waveguiding region below a threshold, below which further propagation of damage is not supported.','Optical communications system and method of protecting an optical route','B2',23,'ipg070109.xml',0,'[-0.02548755,0.002616463,0.004698566,-0.021997442,-0.02398402,0.027354624,0.00052855344,-0.000191704,0.018970722,-0.049303334,0.0027752963,-0.038760148,0.045246527,-0.049707823,0.06023292,-0.030516598,0.060083564,-0.038609836,-0.031441014,-0.0063853473,-0.027198378,-0.09766049,-0.0164276,-0.037041787,0.03016001,-0.08338727,0.038754012,-0.027479956,-0.035591938,0.058594655,-0.047611296,-0.04766751,0.011009712,0.0078033763,-0.016901758,-0.032980498,0.052043695,-0.019093826,-0.024406105,-0.0069557624,0.042380385,-0.022500537,0.051015314,0.0040796665,-0.025825433,0.0045105866,-0.005523569,0.08423042,0.019852648,-0.05731646,-0.024264453,0.0654283,-0.009964833,-0.01597741,0.030689213,-0.0011551493,0.06974428,0.056242254,-0.020870415,-0.00044546864,0.013279205,0.0029271957,-0.021404156,-0.023632303,-0.06770484,0.066511266,-0.009163625,0.03640381,0.015127697,-0.07488842,0.002537135,-0.019212097,0.0096843215,-0.028202252,-0.014574151,-0.04879642,0.025736816,0.03716174,-0.06273019,0.031646617,-0.016571837,-0.036521677,-0.022844331,-0.03442788,0.01859159,-0.019163772,-0.024654198,-0.061309636,0.013378529,0.016440243,0.017166512,-0.015060984,0.059088606,-0.039521724,0.053015634,0.025393516,-0.04419772,0.09475169,0.021761427,0.012438811,0.0070003374,0.06288504,-0.014026941,-0.05456961,0.011936735,0.042619232,0.011624152,-0.0210