insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7164496','utility','7164496','US','1/16/2007','The image correction apparatus includes an image reading unit for reading a print image of an original image, where a mark is given to a defect on an image and an image correction unit for correcting image data of the original image by utilizing the position of the mark on a read image read by the image reading unit. The image correction apparatus efficiently corrects an image defect visually recognized on the print image without using an infrared ray, when the print image is output from image data of the original image.','Image correction apparatus','B2',10,'ipg070116.xml',0,'[0.0322582,-0.017179877,0.058003552,-0.0060004676,-0.0054095746,0.049832065,0.003262268,-0.022158144,0.053523872,-0.02063136,-0.022248657,-0.032720916,0.04939742,-0.02724544,0.020072924,0.0084499605,0.03912016,-0.088392146,-0.020464009,-0.029204631,0.027283233,-0.04404194,-0.017809706,0.02464607,-0.014094261,-0.057283625,-0.040146776,-0.030875275,-0.041667257,0.069986254,-0.0003515294,-0.09662162,0.091485366,0.039047882,0.0075012194,-0.03835349,0.039717868,0.0076177367,0.016247608,0.012182604,0.051460307,-0.061144244,0.03977221,-0.04035245,-0.086889185,0.023983274,-0.010495933,0.01274964,0.05319218,-0.049454562,-0.04212142,0.028437177,0.005501452,-0.0506693,0.04220201,0.006743409,0.054292213,0.04109394,-0.013987612,-0.027731076,0.0017874895,-0.02325176,0.025729185,0.032644425,-0.019828318,0.042498846,0.016083205,-0.0009751731,-0.03201372,-0.042781293,0.060035244,0.005604039,0.009894711,-0.040854692,-0.0010071084,-0.06183739,0.020459624,-0.02166332,-0.003469379,0.06977379,-0.023024952,-0.049874213,-0.06747933,-0.022315523,0.06253843,0.020299135,0.018183937,0.00215887,0.011362664,0.040604185,-0.0076527586,-0.008088025,0.013441191,0.008519686,0.05759456,0.04565259,0.008170018,0.09771011,0.01797934,-0.027445134,