insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7171917','utility','7171917','US','2/6/2007','An asymmetric boat anchor has an unballasted fluke (2), with a tip (6) and a back (8) with a curved edge (10); a shank (4) is mounted on the fluke. The edge (26) of the shank away from the tip (6) of the fluke is curved and the free end of the shank (18) is offset from a plane (30) tangent to the back edge (10) of the fluke and to the edge (26) of the shank. Thus, if the anchor is in a reverse position, contacting the sea ground through the edge of the shank and the back edge of the fluke, it will roll on the edge of the shank and turns to the anchoring position.','Asymmetrical unballasted anchor','B2',13,'ipg070206.xml',0,'[0.011326228,0.04122348,-0.04033469,-0.021621237,-0.007345827,0.03725514,-0.02407511,-0.016046042,0.051431417,-0.046090346,-0.06773606,0.0024043657,0.038042244,-0.02137673,-0.0031712125,0.019172166,0.055622727,-0.09789503,-0.0035833009,-0.084810056,0.03474884,0.0020363196,-0.07315015,-0.01581553,0.051349197,-0.055925325,0.035466745,-0.0042164093,-0.0270167,0.037332423,-0.021578198,-0.014929015,0.04590409,0.0027018825,0.05556821,-0.0054437565,0.0060979663,-0.018300373,-0.013494463,0.026532782,0.07390898,-0.012449229,0.0011853001,-0.061163124,-0.007963384,0.03447353,-0.02780351,0.021020917,0.047600135,-0.067457594,0.006552594,0.032160103,0.03749901,-0.019783167,0.026509617,0.06673481,0.037075162,-0.0016685646,-0.015344453,-0.026112378,0.07416366,-0.005222912,0.009303229,-0.011643451,-0.04269833,0.047781058,0.0451503,-0.00368594,0.016342707,-0.022430588,-0.021888895,-0.090642594,0.023927325,-0.03736911,-0.018091116,-0.056051906,0.019518377,-0.019786539,0.008814674,0.07201473,-0.0056416877,-0.037096478,-0.03632882,-0.011723947,0.0033725267,-0.023818988,-0.028823078,-0.04108097,-0.0022524926,-0.009350796,0.010037509,-0.040059812,-0.015084484,0.022882927,0.01760589,0.