insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7172682','utility','7172682','US','2/6/2007','Disclosed herein is a method and apparatus of immobilizing a biocatalyst on a microfluidic biochip for conducting reactions in the presence of electroosmotic flow. The biochip includes a polymer on its microfluidic flow surfaces, wherein the polymer includes a first substituent selected from ionic groups of the same polarity or precursors thereof, a second substituent that is a hydrophobic group, and a third substituent comprising an immobilized biocatalyst-or precursor thereof. The biochip can be used to conduct multiple sequential biocatalyzed reactions in the presence of electroosmotic flow.','Enzyme immobilization for electroosmotic flow','B2',36,'ipg070206.xml',0,'[-0.014407398,0.0062981285,0.012290193,-0.06379269,0.016375383,0.006857539,-0.0329359,0.050456997,0.006311961,0.009685092,-0.009144789,-0.03833349,0.047451857,-0.09811401,0.033047266,-0.01679059,0.076468274,-0.056676857,-0.008507777,0.015814297,0.014740669,-0.04727068,-0.029532092,0.041882116,0.06568586,-0.07104898,-0.03339772,-0.011731199,-0.017798983,0.057174463,0.06070149,-0.039603904,0.00069767644,-0.04383603,0.02583406,-0.06022795,0.0759121,0.036445174,-0.028332574,0.03161364,0.03756131,-0.028023614,0.024247069,-0.013557844,0.017537834,0.011280956,-0.023090953,0.061375014,0.011663657,0.0029554376,0.020475974,0.018155945,-0.018240338,-0.04949766,0.06596359,0.072387315,0.0023811578,0.056484427,-0.006384436,-0.01064791,-0.029434966,-0.050107714,-0.021830179,0.0050475867,0.010707702,0.06302074,0.037342332,0.028317228,0.017262517,-0.009995634,-0.038873147,-0.03862411,-0.0027621791,-0.04330821,-0.03165821,-0.04127443,0.0109237945,0.0016328964,-0.032046184,0.08996838,-0.00692834,-0.03090821,-0.0515488,0.02701251,0.049823906,-0.0070772683,0.01296461,0.03039996,0.01074425,0.03906076,-0.050766777,-0.031804893,0.018392516,