insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7175497','utility','7175497','US','2/13/2007','A purse that converts into a doll bed, having an upwardly facing basket; fabric mounted in the basket and which extends upwardly from the basket to form an upwardly facing container that may serve as either a purse or a doll bed; straps secured to the upper end of one of the fabric or the basket so that the combination purse and doll bed may be readily carried; the fabric of the purse extends upwardly sufficiently so that the fabric may form a purse or be folded outwardly to form a doll bed; and a fabric hood secured to the interior of the fabric which may lay concave when the fabric is formed into a purse or be lifted to serve as a toy sunshade for a doll when the fabric is formed into a doll bed.','Apparatus operable for transformation between a purse and a toy','B2',2,'ipg070213.xml',0,'[-0.036610056,-0.014363937,-0.0071324483,-0.048390996,0.090836786,0.08115322,-0.009739793,-0.022330176,0.0062757614,0.012708365,-0.043754224,-0.021111948,0.06312583,-0.07387501,0.003205715,0.040269665,0.010911747,-0.05054282,0.0076258145,-0.0073832325,0.005152366,-0.047743298,-0.040965002,0.03897775,0.036287062,-0.10018711,-0.03338704,-0.004883445,-0.061798293,-0.010360503,0.003704602,-0.038553443,0.00053124386,0.007412949,0.011398219,-0.009014795,0.053678025,0.035181228,0.022224898,0.0036274015,0.07160691,-0.01569104,-0.040975958,-0.05787633,0.0041902144,0.027989965,-0.025016928,-0.021352706,0.0041748798,-0.06194688,0.034881935,0.04957551,-0.028626908,-0.0075684004,0.025121028,0.006433187,0.017380401,0.02620829,-0.03197763,0.004277285,0.011145621,-0.036258973,-0.05359039,0.0074554104,-0.026423696,0.07388005,0.006900679,-0.026886703,-0.008518435,0.017547918,0.045836646,0.017234331,-0.016398158,-0.08970816,0.001592416,0.051880796,-0.007831031,-0.0262354,0.000830028,0.04532594,-0.05198604,-0.01206