insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7176745','utility','7176745','US','2/13/2007','The well voltage of a CMOS circuit having low-threshold-voltage MOSFETs is controlled when the power supply is turned on, during normal operation, and when the supply voltage is cut off. The CMOS circuit can thus operate stably with lower power consumption, because latching-up is reduced when the supply voltage is applied to the CMOS circuit or when the supply voltage is cut off, and subthreshold current is decreased during normal operation.','Semiconductor device','B2',4,'ipg070213.xml',0,'[-0.009036061,-0.0096951695,0.0034159988,0.008675596,0.0062712743,-0.004183969,0.00827335,0.013590946,0.016202724,-0.068847075,0.0040205745,0.015683463,0.009150919,-0.08520879,0.0026468178,-0.024610268,0.02325763,-0.080232315,-0.023840455,-0.014699026,0.0474561,-0.08780652,0.00475251,0.010481055,0.01800901,-0.091163255,0.048643716,0.012144133,-0.07420733,0.09297141,-0.021413002,-0.0194056,0.03145323,-0.06669357,0.025186425,-0.080888286,0.02856786,0.008912035,0.012231447,-0.017245287,0.03457641,-0.024066756,-0.015668938,-0.027325867,-0.052710943,0.075724006,-0.04998409,0.030371167,0.069154516,-0.06861261,-0.026654493,0.024590423,0.046914708,0.035606477,0.02761381,0.015264271,0.026985152,0.0357669,-0.010286335,0.049149018,-0.0034197762,0.007783488,-0.006978536,0.021876615,-0.032568134,0.06606626,0.020290708,-0.0006073291,-0.039785866,-0.012946692,-0.07147621,-0.023528183,0.07045395,-0.041928846,0.01689759,-0.011477045,0.01129105,0.02579587,-0.015747698,0.016060943,-0.014678726,-0.037671555,-0.038457368,-0.014814049,0.071967,-0.0131007,-0.061000142,-0.024548186,-9.517074e-06,0.009892727,-0.006833213,-0.027308386,-0.020492543,0.03305422,0.030782834,0.023070278,-0.0068596387,0.13294005,-0.0065550655,-0.011634093,0.038763262,0.02166216,-0.003100839,-0.062223665,0.008884694,0.06586441,0.06562865,0.021