insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7180129','utility','7180129','US','2/20/2007','A method of manufacturing an insulating layer that ensures reproducibility across like manufacturing apparatus. The insulating layer is formed on the substrate by (a) flowing an oxidizing gas at an oxidizing gas flow rate, (b) flowing a first carrier gas at a first carrier gas flow rate while carrying a first impurity including boron flowing at a first impurity flow rate, (c) flowing a second carrier gas at a second carrier gas flow rate while carrying a second impurity including phosphorus flowing at a second impurity flow rate, and (d) flowing a silicon source material at a silicon source flow rate. The second carrier gas flow rate is greater than the first carrier gas flow rate.','Semiconductor device including insulating layer','B2',7,'ipg070220.xml',0,'[0.017277472,0.024562092,0.024202688,0.002479077,0.01320767,0.03914947,-0.04104343,0.047258437,0.078323096,0.052888263,0.022840746,-0.014077492,0.005269016,-0.018972829,0.04596811,0.02549684,0.026212873,-0.036446184,-0.020198986,0.0017349136,0.046836033,-0.09134043,-0.031124007,0.007154894,0.030721202,-0.13221721,-0.015861612,-0.0018789992,0.009062643,0.042860195,-0.026607776,-0.047988094,0.05158545,0.014834367,-0.0024300485,-0.037561126,0.015708895,0.011739067,0.053779956,0.00634368,0.0018892246,0.024526127,0.039828956,-0.05904152,-0.016535921,0.06219428,-0.05658479,0.07543512,0.07409892,-0.039279994,0.03587148,0.025660574,-0.032032672,0.025460714,0.05547957,0.0032594823,0.024628902,0.088109575,-0.017498193,0.023323147,-0.02290271,-0.061345402,-0.017363383,-0.022958279,-0.045228053,0.040835068,0.029357476,0.08116561,0.033162754,-0.0023531008,-0.028366324,0.027179103,0.027776869,-0.034995567,0.017595496,-0.03428788,-0.035598267,-0.0054963343,-0.03535333,0.05875225,-0.027398255,-0.004571835,-0.049200486,0.014082272,0.07934148,0.