insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('10996897','utility','10996897','US','5/4/2021','Storage virtualization techniques allow directories to be stored remotely, for example, by a cloud storage provider, but in a manner that appears to a user or application running on a local computing device as if the directories are stored locally��������even though the data of those directories may not be resident on the local computing device. That is, the contents of directories that may exist in the cloud look and behave as if they were stored locally on a computing device.','Storage virtualization for directories','B2',18,'ipg210504.xml',0,'[-0.06597807,0.006277441,0.05921994,-0.02946479,-0.03162942,0.05744426,0.06303062,0.013728616,0.035872146,-0.0027123888,0.0016418367,0.0020447124,0.07109007,-0.057264145,0.005682477,0.00013030047,0.0105157215,-0.06800986,-0.0085019665,-0.059071846,0.025854314,-0.0036025858,-0.060040586,-0.0055474276,0.0502972,-0.05970853,0.00979831,-0.034479626,-0.016727448,0.008627079,0.07627368,0.0014113657,0.047626592,0.04713491,0.017606448,-0.057589017,0.06037687,-0.0048286347,0.0011251037,-0.02434808,0.03372367,0.020431204,-0.019906623,-0.03187858,0.0042244806,0.10854224,-0.033177797,0.008810651,0.04310432,-0.048256934,0.023375588,-0.015960695,0.029964227,-0.009153644,0.010937422,0.060124908,0.014427223,0.020920873,0.04055794,0.011828069,0.028450957,-0.06364029,-0.015394176,-0.058738068,-0.092958085,0.02922442,0.03884546,-0.037656248,0.0016096003,0.0025732638,-0.0015471011,-0.027006585,0.0761832,-0.09442035,0.008635656,-0.03744938,0.029075833,0.0036983653,0.0063457987,0.054810826,-0.029808784,0.03857972,-0.023195002,-0.018043835,0.086846195,-0.03241604,-0.01834429,-0.0025807181,-0.047558654,-0.04113404,0.009151694,0.023286032,0.07512249,-0.023191363,0.07776894,0.012546336,-0.0046674805,0.108854145,0.009506634,0.04344594,-0.025868233,0.0029273727,-0.0