insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7181883','utility','7181883','US','2/27/2007','A chummer chops up bait and expels the chopped up bait into the water wherein the chummer has a housing with an opening for receiving the bait. A motor has a shaft extending through the housing and has at least one cutting blade for chopping the bait gravitationally falling through the housing. An impeller blade is attached to the shaft, the impeller blade drawing water into the housing, wherein the water is mixed with the chopped up bait and the mixture subsequently expelled from the housing.','Bait chummer','B1',18,'ipg070227.xml',0,'[-0.026466252,-0.0081377765,0.014919197,-0.037313174,0.037921973,0.012764602,-0.042806953,-0.03909899,-0.002995303,-0.008440125,-0.04654056,-0.015730282,0.00934114,-0.09759952,-0.010550209,0.07495856,0.027502932,-0.057171144,-0.0026334503,0.002035884,0.004809111,-0.06513433,-0.054068975,-0.0049918965,0.0674827,-0.119773075,0.020365855,-0.042008266,-0.07871428,0.037876356,0.0042412844,-0.0757231,0.07399151,0.013000475,-0.034378856,-0.034959715,0.000893649,0.050084107,-0.071738794,0.013802288,0.05014218,-0.01752189,0.0121418685,-0.069980115,0.03363877,0.025693193,-0.027131608,0.016716946,0.036097676,-0.02797758,0.07516865,0.012459956,0.0033512602,-0.0048741335,0.076810725,0.029887596,-0.015191341,0.016845424,-0.0050857943,-0.006578086,0.051147472,-0.021434665,-0.03502744,0.037430357,-0.057789236,0.056789286,0.056631066,-0.03175553,0.032716,-0.056605004,-0.060346298,-0.04512991,-0.006670769,-0.05293032,0.004620474,-0.017878996,-0.042262744,0.047915135,-0.026586765,0.042957205,-0.030388486,-0.050719142,-0.04038261,0.0023561793,0.014037336,0.017096564,-0.018240698,-0.034291804,0.014848835,0.027079117,0.010671126,-0.035951205,0.03679712,0.013850391,0.052017704,0.037174642,0.049970362,0.05174238,0.0002592424,0.04753935,0.021801908,0.014957273,0.02573381,-0