insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('7183296','utility','7183296','US','2/27/2007','The present invention comprises novel and known pyrazole derivatives having anti-HIV activity, a process for their manufacture, pharmaceutical compositions and the use of such compounds in medicine. In particular, the compounds of formula I are inhibitors of the human immunodeficiency virus reverse transcriptase enzyme which is involved in viral replication. Consequently the compounds of this invention may be advantageously used as therapeutic agents for HIV infection.','Anti-HIV pyrazole derivatives','B2',12,'ipg070227.xml',0,'[0.0023375703,-0.0020899686,0.0018888364,-0.066529125,0.025070427,0.014929494,0.015365588,0.029392332,-0.009979348,-0.013724023,0.00518004,0.010738277,0.012978519,-0.06291758,-0.027986476,-0.03800457,0.053091522,-0.0285478,0.0327105,0.05942489,0.022134786,-0.056487404,-0.0037074045,0.015155055,0.0066061364,-0.0026850663,-0.0338914,0.09075547,-0.030062223,0.051754773,0.018070899,-0.03779147,0.107927725,-0.00909287,0.0059524053,-0.08108287,0.01844735,0.020668402,0.0067692064,-0.0018683634,0.025144765,-0.010844623,0.0040672803,-0.015397374,0.05762183,0.03199905,-0.04438516,0.022814149,-0.04601212,0.035175223,0.05546677,-0.01164321,0.053811595,-0.0074779196,0.059777524,0.022056762,-0.0057956297,0.02932433,-0.037571993,0.036582027,0.0011358359,-0.05473977,-0.0218644,0.026536476,-0.021701934,0.054991197,0.022136876,0.00059510616,0.025772652,0.005147375,-0.022026628,-0.006081876,0.014713944,-0.028172743,-0.06813431,-0.022131898,0.048714228,0.0727433,-0.032505393,0.06633636,-0.11955777,-0.052947573,-0.022659883,0.024435923,-0.029111398,-0.024320802,-0.014457383,-0.027041122,-0.039666537,0.019567471,-0.020321775,-0.046124417,0.048995137,0.050417803,0.021481615,0.10790525,-0.027287133,0.017314155,0.016003663,-0.002857869,0.052385844,0.029721875,0.016840596,-0.0164390