insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9786863','utility','9786863','US','10/10/2017','Provided is a white organic light emitting device which can improve abnormal light emission and efficiency and reliability of the device.A white organic light emitting device according to an exemplary embodiment of the present invention includes: a first light emitting unit including a first emitting layer between a first electrode and a second electrode; a second light emitting unit including a second emitting layer on the first light emitting unit; and a charge generation layer between the first light emitting unit and the second light emitting unit, and a volume of a metal in the charge generation layer is 1.0% or less of the total volume of the charge generation layer.','White organic light emitting device','B2',13,'ipg171010.xml',0,'[-0.0052408217,-0.034815345,0.025265712,-0.015188293,0.0013594904,0.011830012,-0.02099264,0.027691022,0.024581404,-0.002960962,0.013276101,-0.03405062,0.007669251,-0.046469755,0.0018692485,0.030339632,0.016225973,-0.045298472,0.017470418,0.0045029162,0.011968852,-0.09526451,-0.008104822,-0.0009158564,0.04772457,-0.119153515,0.013859933,-0.0479122,-0.050338082,0.089927636,0.01351113,-0.054143332,0.016426597,-0.019129327,-0.02492615,-0.026386278,0.052237492,-0.02015568,0.00846564,0.01448184,0.09584713,-0.030083204,0.032876354,-0.024750711,-0.06902085,0.036400646,-0.0015804117,0.039963815,0.08129476,-0.07177947,0.026365021,0.050859533,-0.048693523,-0.06244556,0.0026231622,-0.021780668,0.04027996,0.045696225,0.02748166,-0.0016730241,-0.048721027,0.010213324,0.042304065,0.031592455,-0.030224724,0.035338577,0.03458492,0.017266897,-0.023321701,0.0130839,-0.05586908,0.0044907727,0.007851718,-0.0713636,0.023130994,0.03117722,-0.018905051,0.0071645016,-0.016028564,0.10426183,-0.03189873,-0.039564352,-0.02831071,-0.044984758,-0.0076216315,-0.013576818,-0.03