insert into patents_data(id, type, number, country, date, abstract, title, kind, num_claims, filename, withdrawn,abstract_embeddings) values('9787409','utility','9787409','US','10/10/2017','A multi-channel free-space optical wavelength division multiplexing system for optical quantum communication includes a transmitter configured to encode an input signal into a weak optical signal carrying quantum information, and to transmit the weak optical signal over a plurality of frequency channels in free space, each of the plurality of frequency channels corresponding to a plurality of photons of the weak optical signal, and a receiver configured to receive and decode the weak optical signal.','High-speed optical quantum communication system based on mode-locked laser pulses','B1',20,'ipg171010.xml',0,'[-0.0024559863,-0.034256436,0.04810468,-0.052985817,0.02146238,0.042995222,-0.0085978415,0.032305624,0.04538475,-0.035669148,0.025192115,-0.046613283,0.014165121,-0.043009065,0.008761186,-0.05239857,0.03125933,-0.06939808,-0.06405975,-0.015073301,0.017705927,-0.12261303,-0.06360834,0.03775704,-0.011080743,-0.08126725,-0.0015351038,-0.04829765,-0.03219333,0.037603952,0.030060736,-0.058562838,0.037518624,0.0043785046,0.012945963,-0.011231717,0.031107076,0.013055698,0.009553371,-0.04101076,0.024048287,-0.046333134,0.0027963477,-0.012680416,-0.04133952,0.06120664,-0.07582803,-0.013757581,0.032387864,-0.033101667,0.008809205,0.021245517,-0.034777556,-0.02496076,-0.008637882,-0.027700745,0.03078507,0.05927185,0.04005133,0.04893729,-0.024251036,-0.010726389,0.048244245,0.0416049,-0.07539877,0.029891487,0.00260819,-0.0011952287,-0.030051313,-0.04928012,-0.028974479,-0.020457663,0.051429477,-0.048173156,-0.02297386,-0.038601696,0.03155899,-0.02548467,-0.025216814,0.08817315,-0.043560654,-0.050065357,-0.01283251,0.02112301,0.06285906,-0.029712984,-0.0287737,-0.04005463,-0.009344936,0.05190821,0.03706451,-0.018276595,0.047246132,-0.020614836,0.057763763,0.014176161,-0.05320295,0.102671